def find(folder,suf):
    for f in sorted(os.listdir('src/'+folder)):
        if f.endswith('.jpg') and suf in f and 'wide' not in f: return 'src/'+folder+'/'+f
    raise SystemExit(f'missing {folder} {suf}')
def crop(src,box,name):
    p=T+name; Image.open(src).convert('RGB').crop(box).save(p); return p
only=sys.argv[1:] 
for folder,out,num,word,t1,t2,sub,items,pin in C:
    if only and out not in only: continue
    files=[]; labels=[]
    for suf,lab in items:
        if suf=='AFTER':
            ba=[f for f in os.listdir('src/'+folder) if 'before-after' in f][0]; im=Image.open('src/'+folder+'/'+ba); w,h=im.size
            p=T+out+'-after.png'; im.crop((w//2+8,0,w,h)).save(p); files.append(p)
        else: files.append(find(folder,suf))
        labels.append(lab)
    hero=files[0]; im=Image.open(hero); w,h=im.size
    a=crop(hero,(0,0,w//2,h),out+'-hl.png'); b=crop(hero,(w//2,0,w,h),out+'-hr.png')
    mid=find(folder,pin) if pin else files[1]
    pin_cozy([a,mid,b]+files,num,word,t1,t2,sub,['','','']+labels,O+out+'-cozy.jpg',seed=hash(out)%97+5)
    print('ok',out)
